local HairbrushMaker = {}
local PRODUCTS = {
    iron_hairbrush = { name = "Železna ščetka za lase", ironCost = 1, woodCost = 3, leatherCost = 2, time = 5, cost = 140, prestige = 3, happiness = 2, description = "Železna ščetka za nego las." },
    bronze_hairbrush = { name = "Bronasta ščetka za lase", bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 2, time = 7, cost = 340, prestige = 5, happiness = 3, description = "Bronasta ščetka za mehke lase." },
    silver_hairbrush = { name = "Srebrna ščetka za lase", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 2, time = 11, cost = 830, prestige = 10, happiness = 4, description = "Srebrna ščetka za plemiške lase." },
    gilded_hairbrush = { name = "Pozlačena ščetka za lase", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 2, time = 15, cost = 1800, prestige = 19, happiness = 5, description = "Pozlačena ščetka za dvorne lase." },
    jewel_set_hairbrush = { name = "Draguljasta ščetka za lase", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 2, time = 19, cost = 3900, prestige = 35, happiness = 7, description = "Draguljasta ščetka za kraljeve lase." },
    royal_sovereign_hairbrush = { name = "Kraljevski suverena ščetka za lase", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 2, time = 26, cost = 8400, prestige = 67, happiness = 13, description = "Suverena ščetka z biseri za krono." },
}
local BUILDINGS = {
    hairbrush_workshop = { name = "Ščetkarska delavnica", cost = { gold = 310, wood = 185, stone = 125, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    hairbrush_house = { name = "Ščetkarska hiša", cost = { gold = 1150, wood = 365, stone = 260, silver = 6, iron = 6 }, upkeep = 24, qualityBonus = 18 },
    master_hairbrush_atelier = { name = "Mojstrski ščetkarski atelje", cost = { gold = 2920, wood = 425, stone = 505, silver = 34, gold = 7 }, upkeep = 69, qualityBonus = 30 },
    sovereign_hairbrush_palace = { name = "Suverena ščetkarska palača", cost = { gold = 12650, wood = 650, stone = 815, gold = 81, jewel = 18 }, upkeep = 248, qualityBonus = 55, prestigeBonus = 50 },
}
HairbrushMaker.ironStock = 10; HairbrushMaker.bronzeStock = 8; HairbrushMaker.woodStock = 18; HairbrushMaker.leatherStock = 12; HairbrushMaker.silverStock = 8; HairbrushMaker.goldStock = 6; HairbrushMaker.jewelStock = 4; HairbrushMaker.pearlStock = 4
HairbrushMaker.productStock = {}; HairbrushMaker.buildings = {}; HairbrushMaker.maker = nil; HairbrushMaker.activeMaking = {}; HairbrushMaker.totalProducts = 0; HairbrushMaker.dayTimer = 0
function HairbrushMaker.init() HairbrushMaker.ironStock=10; HairbrushMaker.bronzeStock=8; HairbrushMaker.woodStock=18; HairbrushMaker.leatherStock=12; HairbrushMaker.silverStock=8; HairbrushMaker.goldStock=6; HairbrushMaker.jewelStock=4; HairbrushMaker.pearlStock=4; HairbrushMaker.productStock={}; HairbrushMaker.buildings={}; HairbrushMaker.maker=nil; HairbrushMaker.activeMaking={}; HairbrushMaker.totalProducts=0; HairbrushMaker.dayTimer=0; print("[HairbrushMaker] Royal Hairbrush Maker System initialized (6 products, 4 buildings)") end
function HairbrushMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HairbrushMaker.maker={name=n or ("Ščetkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ščetkar najet: %s (spretnost: %d)",HairbrushMaker.maker.name,s),"success") end; return true end
function HairbrushMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HairbrushMaker.build(id) local ok,e=HairbrushMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HairbrushMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HairbrushMaker.getQualityBonus() local b=0; for _,bd in ipairs(HairbrushMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HairbrushMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HairbrushMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HairbrushMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HairbrushMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HairbrushMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HairbrushMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HairbrushMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HairbrushMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HairbrushMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HairbrushMaker.buildings==0 then return false,"Potrebna ščetkarska delavnica" end; if not HairbrushMaker.maker then return false,"Potreben ščetkar" end; return true end
function HairbrushMaker.make(pt,qty) qty=qty or 1; local ok,e=HairbrushMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HairbrushMaker.ironStock=HairbrushMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HairbrushMaker.bronzeStock=HairbrushMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HairbrushMaker.woodStock=HairbrushMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HairbrushMaker.leatherStock=HairbrushMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HairbrushMaker.silverStock=HairbrushMaker.silverStock-d.silverCost*qty end; if d.goldCost then HairbrushMaker.goldStock=HairbrushMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HairbrushMaker.jewelStock=HairbrushMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HairbrushMaker.pearlStock=HairbrushMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HairbrushMaker.maker then t=math.max(1,t-math.floor(HairbrushMaker.maker.skill/13)) end; table.insert(HairbrushMaker.activeMaking,{id="hairbrush_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HairbrushMaker.completeMaking(m) local q=1.0+(HairbrushMaker.getQualityBonus()/100); if HairbrushMaker.maker then q=q+(HairbrushMaker.maker.skill/140) end; q=math.min(2.5,q); HairbrushMaker.productStock[m.productType]=(HairbrushMaker.productStock[m.productType] or 0)+m.quantity; HairbrushMaker.totalProducts=HairbrushMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HairbrushMaker.maker then HairbrushMaker.maker.itemsMade=HairbrushMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HairbrushMaker.maker.skill=math.min(100,HairbrushMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ščetka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hairbrush.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HairbrushMaker.update(dt) if not _G.state then return end; HairbrushMaker.dayTimer=HairbrushMaker.dayTimer+dt; if HairbrushMaker.dayTimer>=30 then HairbrushMaker.dayTimer=0; for i=#HairbrushMaker.activeMaking,1,-1 do local m=HairbrushMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HairbrushMaker.completeMaking(m); table.remove(HairbrushMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HairbrushMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HairbrushMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HairbrushMaker.getStats() return {ironStock=HairbrushMaker.ironStock,bronzeStock=HairbrushMaker.bronzeStock,woodStock=HairbrushMaker.woodStock,leatherStock=HairbrushMaker.leatherStock,silverStock=HairbrushMaker.silverStock,goldStock=HairbrushMaker.goldStock,jewelStock=HairbrushMaker.jewelStock,pearlStock=HairbrushMaker.pearlStock,productStock=HairbrushMaker.productStock,numBuildings=#HairbrushMaker.buildings,hasMaker=HairbrushMaker.maker~=nil,makerName=HairbrushMaker.maker and HairbrushMaker.maker.name or "—",makerSkill=HairbrushMaker.maker and HairbrushMaker.maker.skill or 0,activeMaking=#HairbrushMaker.activeMaking,totalProducts=HairbrushMaker.totalProducts} end
return HairbrushMaker
